from collections import OrderedDict

def trace(capacity, ops):
    cache = OrderedDict()
    results = []
    evicted = []
    hits = 0
    misses = 0

    for op in ops:
        if op[0] == "put":
            _, key, value = op
            if key in cache:
                cache[key] = value
            else:
                cache[key] = value
                if len(cache) > capacity:
                    evicted_key, _ = cache.popitem(last=False)
                    evicted.append(evicted_key)
        elif op[0] == "get":
            _, key = op
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
                hits += 1
            else:
                results.append(None)
                misses += 1
        elif op[0] == "peek":
            _, key = op
            if key in cache:
                results.append(cache[key])
                hits += 1
            else:
                results.append(None)
                misses += 1

    return {
        "results": results,
        "evicted": evicted,
        "hits": hits,
        "misses": misses
    }

