        if i == best_index:
            sub = math.floor(sub * 0.9)
        total += sub

    return total

import math

def cart_total(items, coupon=0):
    if not (0 <= coupon <= 100):
        raise ValueError("Coupon percentage must be between 0 and 100")

    if not items:
        return 0

    # Calculate undiscounted subtotals and find the best qualifying line index
    subtotals = []
    best_index = -1
    max_subtotal = -1

    for i, item in enumerate(items):
        sub = item["unit_price"] * item["qty"]
        subtotals.append(sub)
        if item["qty"] >= 10:
            if sub > max_subtotal:
                max_subtotal = sub
                best_index = i

    total = 0
    for i, item in enumerate(items):
        sub = subtotals[i]
        if i == best_index:
            sub = math.floor(sub * 0.9)
        total += sub

    if coupon > 0:
        total = math.floor(total * (1 - coupon / 100))

    return total

