def secs(s: str) -> int:
    total_seconds = 0

    # Find all terms consisting of digits followed by a unit (d, h, m, s)
    matches = re.findall(r'(\d+)([dhms])', s)

    for val_str, unit in matches:
        val = int(val_str)

        if unit == 'd':
            total_seconds += val * 86400
        elif unit == 'h':
            total_seconds += val * 3600
        elif unit == 'm':
            total_seconds += val * 60
        elif unit == 's':
            total_seconds += val

    return total_seconds

