def bins(values, edges):
    num_bins = len(edges) - 1
    counts = [0] * num_bins

    if num_bins <= 0:
        return counts

    min_val = edges[0]
    max_val = edges[-1]

    for val in values:
        if min_val <= val < max_val:
            # Binary search to find the correct bin
            low = 0
            high = num_bins - 1

            while low <= high:
                mid = (low + high) // 2
                if edges[mid] <= val < edges[mid + 1]:
                    counts[mid] += 1
                    break
                elif val < edges[mid]:
                    high = mid - 1
                else:
                    low = mid + 1

    return counts

