def bins(values, edges):
    num_bins = len(edges) - 1
    counts = [0] * num_bins

    if num_bins <= 0:
        return (0, counts, 0)

    min_val = edges[0]
    max_val = edges[-1]

    under = 0
    over = 0

    # Identify zero-width bins and their exact values
    # A zero-width bin occurs when edges[i] == edges[i+1]
    # It acts as a catch-bin for exactly that edge value.
    # If there are multiple identical zero-width bins, the first one scanning left-to-right takes it.

    for val in values:
        if val <= min_val:
            under += 1
        elif val > max_val:
            over += 1
        else:
            # Check for zero-width bin matching `val` first
            matched_zero_width = False
            for i in range(num_bins):
                if edges[i] == edges[i + 1] and val == edges[i]:
                    counts[i] += 1
                    matched_zero_width = True
                    break

            if matched_zero_width:
                continue

            # Otherwise, follow the standard (edges[i], edges[i+1]] rule using binary search
            low = 0
            high = num_bins - 1

            while low <= high:
                mid = (low + high) // 2
                # Note: zero-width bins can never match here because val != edges[mid] 
                # (since if it equaled any edge, the zero-width check above would have caught it 
                # if such a zero-width bin existed, or strictly increasing intervals handle it).
                if edges[mid] < val <= edges[mid + 1]:
                    counts[mid] += 1
                    break
                elif val <= edges[mid]:
                    high = mid - 1
                else:
                    low = mid + 1

    return (under, counts, over)

