        return []

    output = []
    for line in lines:
        if line and (line[0] == ' ' or line[0] == '\t'):
            # It's a continuation line
            if not output:
                # No previous line; stand alone with leading whitespace stripped
                output.append(line.lstrip(' \t'))
            else:
                # Fold into the previous output line:
                # Replace leading run of whitespace with a single space and append
                stripped = line.lstrip(' \t')
                output[-1] = output[-1] + ' ' + stripped
        else:
            # Starts a new output line, unchanged
            output.append(line)

    return output

