def fold(lines):
    if lines is None:
        raise ValueError("Input lines cannot be None")

    output = []
    for line in lines:
        if line is None:
            raise ValueError("Input line cannot be None")

        if line == "":
            # Empty string produces no output and terminates the current fold group
            output.append(None)
            continue

        if line and (line[0] == ' ' or line[0] == '\t'):
            # It's a continuation line
            # Find the last non-None output line or check if output is effectively empty/terminated
            last_idx = -1
            for i in range(len(output) - 1, -1, -1):
                if output[i] is not None:
                    last_idx = i
                    break

            if last_idx == -1:
                # No previous line (or terminated by empty string); stand alone with leading whitespace stripped
                output.append(line.lstrip(' \t'))
            else:
                # Fold into the previous active output line
                stripped = line.lstrip(' \t')
                output[last_idx] = output[last_idx] + ' ' + stripped
        else:
            # Starts a new output line, unchanged
            output.append(line)

    # Filter out None markers (from empty input entries)
    active_output = [l for l in output if l is not None]

    # Collapse consecutive identical output lines
    if not active_output:
        return []

    collapsed = []
    current_line = active_output[0]
    count = 1

    for line in active_output[1:]:
        if line == current_line:
            count += 1
        else:
            if count >= 2:
                collapsed.append(f"{count} x {current_line}")
            else:
                collapsed.append(current_line)
            current_line = line
            count = 1

    # Don't forget the last group
    if count >= 2:
        collapsed.append(f"{count} x {current_line}")
    else:
        collapsed.append(current_line)

    return collapsed

