def squash(path: str) -> str:
    if not path:
        return "."

    is_absolute = path.startswith("/")

    # Split the path by "/"
    parts = path.split("/")

    # Filter out empty parts (from multiple slashes) and "." segments
    filtered_parts = []
    for part in parts:
        if part == "" or part == ".":
            continue
        filtered_parts.append(part)

    # Reconstruct the path
    result = "/".join(filtered_parts)

    if is_absolute:
        result = "/" + result
    elif not result:
        result = "."

    return result

def squash(path: str) -> str:
    if not path:
        return "."

    is_absolute = path.startswith("/")
    parts = path.split("/")

    stack = []
    for part in parts:
        if part == "" or part == ".":
            continue
        elif part == "..":
            if is_absolute:
                # Absolute path: ".." pops if there's something to pop, otherwise clamp at root (do nothing)
                if stack:
                    stack.pop()
            else:
                # Relative path: ".." pops if stack has real segments, otherwise it stays
                if stack and stack[-1] != "..":
                    stack.pop()
                else:
                    stack.append("..")
        else:
            stack.append(part)

    result = "/".join(stack)

    if is_absolute:
        result = "/" + result
    elif not result:
        result = "."

    return result

