def allow(events, limit, window):
    allowed_timestamps = []
    result = []

    for t in events:
        cutoff = t - window
        # Remove timestamps outside the sliding window
        while allowed_timestamps and allowed_timestamps[0] <= cutoff:
            allowed_timestamps.pop(0)

        # Check if adding the current event stays within the limit
        if len(allowed_timestamps) < limit:
            allowed_timestamps.append(t)
            result.append(True)
        else:
            result.append(False)

    return result

