def route(article_tags, subscriptions):
    matched_users = set()

    # Clean article tags: strip whitespace, lowercase, and ignore empty/whitespace-only tags
    article_tags_set = {
        tag.strip().lower() 
        for tag in article_tags 
        if tag and tag.strip()
    }

    for user, tags in subscriptions.items():
