def run(ops):
    stack = []
    # History of mutating operations: each entry is a dict or tuple describing the op.
    # We'll store:
    # For push: {"type": "push", "value": N}
    # For pop: {"type": "pop", "value": popped_val}
    undo_stack = []
    redo_stack = []

    for op in ops:
        if op.startswith("push:"):
            val = int(op.split(":")[1])
            stack.append(val)
            undo_stack.append({"type": "push", "value": val})
            redo_stack.clear()
        elif op == "pop":
            val = stack.pop()
            undo_stack.append({"type": "pop", "value": val})
            redo_stack.clear()
        elif op == "undo":
            if undo_stack:
                action = undo_stack.pop()
                if action["type"] == "push":
                    # Undo a push by popping the value
                    stack.pop()
                elif action["type"] == "pop":
                    # Undo a pop by pushing the value back
                    stack.append(action["value"])
                redo_stack.append(action)
        elif op == "redo":
            if redo_stack:
                action = redo_stack.pop()
                if action["type"] == "push":
                    # Redo a push by pushing the value again
                    stack.append(action["value"])
                elif action["type"] == "pop":
                    # Redo a pop by popping the value again
                    stack.pop()
                undo_stack.append(action)

    return stack

def run(ops):
    stack = []
    # History of mutating operations/transactions.
    # Each entry in undo_stack is either:
    # - A single op dict: {"type": "push", "value": N} or {"type": "pop", "value": N}
    # - A transaction list of op dicts: [{"type": "push", "value": N}, ...]
    undo_stack = []
    redo_stack = []

    in_transaction = False
    current_tx = []

    for op in ops:
        if op == "begin":
            in_transaction = True
            current_tx = []
        elif op == "commit":
            in_transaction = False
            if current_tx:
                undo_stack.append(current_tx)
                redo_stack.clear()
            current_tx = []
        elif op.startswith("push:"):
            val = int(op.split(":")[1])
            stack.append(val)
            action = {"type": "push", "value": val}
            if in_transaction:
                current_tx.append(action)
            else:
                undo_stack.append(action)
                redo_stack.clear()
        elif op == "pop":
            val = stack.pop()
            action = {"type": "pop", "value": val}
            if in_transaction:
                current_tx.append(action)
            else:
                undo_stack.append(action)
                redo_stack.clear()
        elif op == "undo":
            if undo_stack:
                item = undo_stack.pop()
                # item can be a single action dict or a list of action dicts (transaction)
                actions = item if isinstance(item, list) else [item]
                # To undo a batch of actions, we must apply them in reverse order
                for action in reversed(actions):
                    if action["type"] == "push":
                        stack.pop()
                    elif action["type"] == "pop":
                        stack.append(action["value"])
                redo_stack.append(item)
        elif op == "redo":
            if redo_stack:
                item = redo_stack.pop()
                actions = item if isinstance(item, list) else [item]
                # To redo a batch of actions, apply them in their original order
                for action in actions:
                    if action["type"] == "push":
                        stack.append(action["value"])
                    elif action["type"] == "pop":
                        stack.pop()
                undo_stack.append(item)

    # If an input ends with an open transaction, treat it as committed.
    if in_transaction and current_tx:
        undo_stack.append(current_tx)
        redo_stack.clear()

    return stack

