import re

def cmp(a: str, b: str) -> int:
    def parse_tag(tag: str):
        if not tag:
            return []
        # Split into maximal runs of digits and non-digits
        # re.findall splits non-digits and digits into separate chunks
        chunks = re.findall(r'\d+|\D+', tag)
        result = []
        for chunk in chunks:
            if chunk.isdigit():
                result.append((0, int(chunk)))  # digit run
            else:
                result.append((1, chunk))       # non-digit run
        return result

    def parse(v: str):
        if "-" in v:
            numeric_part, tag = v.split("-", 1)
        else:
            numeric_part, tag = v, None

        parts = [int(p) for p in numeric_part.split(".")]
        return parts, parse_tag(tag) if tag is not None else None

    parts_a, tag_a = parse(a)
    parts_b, tag_b = parse(b)

    max_len = max(len(parts_a), len(parts_b))
    parts_a.extend([0] * (max_len - len(parts_a)))
    parts_b.extend([0] * (max_len - len(parts_b)))

    for x, y in zip(parts_a, parts_b):
        if x < y:
            return -1
        if x > y:
            return 1

    # Numeric parts are equal; now compare tags
    # A release (tag_is None) is newer than a pre-release (tag is not None)
    if tag_a is None and tag_b is None:
        return 0
    if tag_a is not None and tag_b is None:
        return -1
    if tag_a is None and tag_b is not None:
        return 1

    # Both have pre-release tags, compare chunk by chunk
    max_tag_len = max(len(tag_a), len(tag_b))
    # Pad with a dummy or handle lengths using prefix rule
    for i in range(max_tag_len):
        if i >= len(tag_a):
            return -1  # tag_a is a prefix of tag_b, so tag_a is shorter -> older
        if i >= len(tag_b):
            return 1   # tag_b is a prefix of tag_a, so tag_b is shorter -> older

        type_a, val_a = tag_a[i]
        type_b, val_b = tag_b[i]

        if type_a != type_b:
            # Digit run (0) sorts BEFORE a non-digit run (1)
            return -1 if type_a < type_b else 1

        # Same type
        if val_a < val_b:
            return -1
        if val_a > val_b:
            return 1

    return 0

