    if not text:
        return []

    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_length = 0

    for word in words:
        word_len = len(word)
        # If the line is empty, we must take the word even if it overflows
        if not current_line:
            current_line.append(word)
            current_length = word_len
        else:
            # Check if adding the word (plus a space) exceeds width
            if current_length + 1 + word_len <= width:
                current_line.append(word)
                current_length += 1 + word_len
            else:
                lines.append(" ".join(current_line))
                current_line = [word]
                current_length = word_len

    if current_line:
        lines.append(" ".join(current_line))

    return lines

